    if (!iris) return null;
    let amount;
    try { amount = BigInt(args.fromAmount); } catch { return null; }
    const maxFee = computeSatoraCctpMaxFee(amount, iris.bpsHundredths);
    if (maxFee <= 0n || maxFee >= amount) return null;
