  // creation's target is pinned separately, at creation).
  const postCctpNetSats = (netSats) => bridge
    ? Number(BigInt(Math.round(netSats)) * BigInt(bridge.netSourceAmountRaw) / BigInt(args.fromAmount))
    : netSats;
