function milestoneLegTokenDecimals(record, legIndex, side) {
  const leg = record.legs[legIndex];
  if (!leg) return 18;
  // The 1Click families' decimals (2026-11-14): natives at
  // their own scales (NEAR 24, XRP 6, the UTXO three 8, APT
  // 8), family tokens from their curated lists.
  const famDec = (chainKey, tokenAddress) => {
    if (chainKey === "near") return tokenAddress == null || String(tokenAddress).toLowerCase() === NEAR_SWAP_NATIVE_TOKEN ? 24
      : (NEAR_TOKENS.find(t => String(t.address).toLowerCase() === String(tokenAddress).toLowerCase())?.decimals ?? 6);
    if (chainKey === "xrpl") return 6;
    if (chainKey === "litecoin" || chainKey === "dogecoin" || chainKey === "bitcoincash") return 8;
    if (chainKey === "aptos") return tokenAddress == null || String(tokenAddress).toLowerCase() === APTOS_SWAP_NATIVE_TOKEN ? 8
      : (APTOS_TOKENS.find(t => String(t.address).toLowerCase() === String(tokenAddress).toLowerCase())?.decimals ?? 6);
    return null;
  };
  if (side === "to") {
    const fd = famDec(leg.toChainKey, leg.toTokenAddress);
    if (fd != null) return fd;
    if (leg.toChainKey === "sui") return isDestNativeToken("sui", leg.toTokenAddress) ? 9 : (SUI_TOKENS.find(t => suiCoinTypeEq(t.address, leg.toTokenAddress))?.decimals ?? 6);
    if (leg.toChainKey === "solana") return 6;
    if (leg.toChainKey === "polkadot") return 10;
    if (leg.toChainKey === "tron") return TRON_TOKENS.find(t => String(t.address) === String(leg.toTokenAddress))?.decimals ?? 6;
    if (leg.toChainKey === "ton") return isDestNativeToken("ton", leg.toTokenAddress) ? 9 : 6;
    const t = (NETWORKS[leg.toChainKey]?.tokens || []).find(x => String(x.address).toLowerCase() === String(leg.toTokenAddress || "").toLowerCase());
    if (t) return t.decimals;
    return isDestNativeToken(leg.toChainKey, leg.toTokenAddress) ? 18 : 18;
  }
  const fdFrom = famDec(leg.fromChainKey, leg.fromTokenAddress);
  if (fdFrom != null) return fdFrom;
  if (leg.fromChainKey === "polkadot") return 10;
  if (leg.fromChainKey === "ton") return isDestNativeToken("ton", leg.fromTokenAddress) ? 9 : 6;
  return 18;
}
/** Re-point a milestone record's Arkade legs at the booted
 *  session's real address (cheapest-entry, 2026-11-14):
 *  legs through Arkade are searched under the deferred
 *  session marker (ARKADE_SESSION_ADDRESS) whenever the
 *  address book had no Arkade entry, and the marker must
 *  never reach a creation — before a leg is quoted or
 *  executed, its Arkade-side addresses become the session's
 *  own address. A FINAL Arkade leg's destination is the
 *  user's chosen endpoint and is never re-pointed. Returns
 *  the legs that still carry the marker afterwards (the
 *  runner refuses those before anything is funded). */
export function resolveMilestoneArkadeAddresses(record, arkadeAddress) {
  if (!record?.legs?.length) return [];
  const addr = typeof arkadeAddress === "string" && arkadeAddress.trim() ? arkadeAddress.trim() : null;
  const last = record.legs.length - 1;
  if (addr) {
    record.legs.forEach((leg, i) => {
      if (leg.fromChainKey === "arkade") leg.fromAddress = addr;
      if (leg.toChainKey === "arkade" && i < last) leg.toAddress = addr;
    });
  }
  return record.legs.filter((leg, i) => leg.fromAddress === ARKADE_SESSION_ADDRESS || (i < last && leg.toAddress === ARKADE_SESSION_ADDRESS));
}
